CREATE TABLE spaces(listing_id uuid REFERENCES listings ON DELETE CASCADE,space_version integer CHECK(space_version>0),objects_version integer NOT NULL DEFAULT 1 CHECK(objects_version>0),bundle jsonb NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(listing_id,space_version));
ALTER TABLE room_states ADD CONSTRAINT state_source_space FOREIGN KEY(listing_id,source_space_version) REFERENCES spaces;
CREATE TABLE placement_sets(set_id uuid PRIMARY KEY,listing_id uuid NOT NULL REFERENCES listings ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,resource_version integer NOT NULL CHECK(resource_version>0),space_kind varchar(15) NOT NULL CHECK(space_kind IN ('SPACE','ROOM_STATE')),space_version integer NOT NULL,room_state_id uuid REFERENCES room_states,collision_report jsonb,is_stale boolean NOT NULL DEFAULT false,saved_at timestamptz NOT NULL,deleted_at timestamptz,UNIQUE(owner_id,listing_id),FOREIGN KEY(listing_id,space_version) REFERENCES spaces);
CREATE TABLE placement_items(set_id uuid REFERENCES placement_sets ON DELETE CASCADE,placement_id uuid NOT NULL,ordinal integer NOT NULL,furniture_id uuid NOT NULL,model_version integer NOT NULL,position_x double precision NOT NULL,position_y double precision NOT NULL,position_z double precision NOT NULL,rotation_x double precision NOT NULL,rotation_y double precision NOT NULL,rotation_z double precision NOT NULL,rotation_w double precision NOT NULL,PRIMARY KEY(set_id,placement_id),UNIQUE(set_id,furniture_id),FOREIGN KEY(furniture_id,model_version) REFERENCES furniture_models);
CREATE INDEX placement_furniture_reference ON placement_items(furniture_id);
